import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listTeamPostsHandler } from "../handlers/listTeamPostsHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof listTeamPostsHandler>>;

export function useListTeamPosts(
  teamname: string,
  category?: string | null,
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listTeamPosts", teamname, category, bookmark],
    queryFn: () => listTeamPostsHandler(teamname, category, bookmark),
    ...options,
  });
}
